examples.template:
MonarchButton({{trigger}}, variant: .secondary) { isChoosing = true }
    .sheet(isPresented: $isChoosing) {
        VStack(alignment: .leading, spacing: 0) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                Text({{title}}).monarchTextStyle(.heading).accessibilityAddTraits(.isHeader)
                Text({{description}}).monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                MonarchRadioCardGroup(
                    {{title}},
                    selection: $audience,
                    options: [
                        MonarchRadioCardOption({{choices.0.value}}, title: {{choices.0.label}}, description: {{choices.0.description}}),
                        MonarchRadioCardOption({{choices.1.value}}, title: {{choices.1.label}}, description: {{choices.1.description}}),
                    ]
                )
            }
            .padding(theme.spacing.space6)
            Divider()
            HStack(spacing: theme.spacing.space2) {
                Spacer()
                MonarchButton("Cancel", variant: .secondary) { isChoosing = false }
                MonarchButton({{confirmLabel}}) { isChoosing = false }
            }
            .padding(theme.spacing.space4)
            .background(theme.colors.bgSubtle)
        }
        .presentationDetents([.height(500)])
    }

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var isChoosing = false
@State private var audience: String? = {{defaultValue}}

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var isChoosing = false
@State private var audience: String? = "private"

examples.code:
MonarchButton("Save view", variant: .secondary) { isChoosing = true }
    .sheet(isPresented: $isChoosing) {
        VStack(alignment: .leading, spacing: 0) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                Text("Who can see this view?").monarchTextStyle(.heading).accessibilityAddTraits(.isHeader)
                Text("You can change this later from the view’s settings.").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                MonarchRadioCardGroup(
                    "Who can see this view?",
                    selection: $audience,
                    options: [
                        MonarchRadioCardOption("private", title: "Only me", description: "The view is listed only for you."),
                        MonarchRadioCardOption("shared", title: "Everyone in the workspace", description: "Members see it in their sidebar and can open it."),
                    ]
                )
            }
            .padding(theme.spacing.space6)
            Divider()
            HStack(spacing: theme.spacing.space2) {
                Spacer()
                MonarchButton("Cancel", variant: .secondary) { isChoosing = false }
                MonarchButton("Save view") { isChoosing = false }
            }
            .padding(theme.spacing.space4)
            .background(theme.colors.bgSubtle)
        }
        .presentationDetents([.height(500)])
    }
